def generate_pdf(content: str, output_path: Path):
    """Generate PDF from markdown content with rich formatting using reportlab.

    The inline formatting is the model's text, so its markup can be malformed:
    overlapping emphasis ("**bold *italic** tail*") becomes interleaved tags
    like '<b><i></b>', which reportlab refuses ("Parse error: saw </b> instead
    of expected </i>", MS02 2026-10-17..23) and which used to fail the WHOLE
    artifact. A paragraph whose markup does not parse is set as plain text,
    and a document that still fails to build is rebuilt from plain lines.
    """
    from reportlab.lib.pagesizes import letter
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer
    from reportlab.lib.units import inch
    import html

    doc = SimpleDocTemplate(str(output_path), pagesize=letter,
                           leftMargin=inch, rightMargin=inch,
                           topMargin=inch, bottomMargin=inch)
    styles = getSampleStyleSheet()

    # Add custom styles for bullets
    styles.add(ParagraphStyle(name='BulletText', parent=styles['Normal'],
                              leftIndent=20, bulletIndent=10))
    story = []

    def escape_xml(text):
        """Escape XML special characters for reportlab."""
        # Escape &, <, > but preserve our markup tags
        text = text.replace('&', '&amp;')
        text = text.replace('<', '&lt;')
        text = text.replace('>', '&gt;')
        return text

    def process_inline_formatting(text):
        """Convert markdown inline formatting to reportlab markup."""
        # First escape XML special characters
        text = escape_xml(text)
        # Bold: **text** or __text__ -> <b>text</b>
        text = re.sub(r'\*\*(.+?)\*\*', r'<b>\1</b>', text)
        text = re.sub(r'(?<!\w)__(.+?)__(?!\w)', r'<b>\1</b>', text)
        # Italic: *text* or _text_ -> <i>text</i>. Underscores inside a word
        # (snake_case identifiers) are not emphasis.
        text = re.sub(r'(?<!\*)\*([^*]+)\*(?!\*)', r'<i>\1</i>', text)
        text = re.sub(r'(?<![\w_])_([^_]+)_(?![\w_])', r'<i>\1</i>', text)
        # Code: `text` -> <font face="Courier">text</font>
        text = re.sub(r'`(.+?)`', r'<font face="Courier">\1</font>', text)
        return text

    def paragraph(text, style, prefix=''):
        """``prefix`` + ``text`` with its inline formatting; plain when the
        resulting markup does not parse."""
        try:
            return Paragraph(prefix + process_inline_formatting(text), style)
        except ValueError as e:
            print(f"[ARTIFACT] PDF line set as plain text (markup did not parse): {e}")
            return Paragraph(prefix + escape_xml(text), style)

    lines = content.split('\n')
    for line in lines:
        # Headers
        if line.startswith('# '):
            story.append(paragraph(line[2:], styles['Heading1']))
        elif line.startswith('## '):
            story.append(paragraph(line[3:], styles['Heading2']))
        elif line.startswith('### '):
            story.append(paragraph(line[4:], styles['Heading3']))
        # Bullet points
        elif line.strip().startswith('- ') or line.strip().startswith('* '):
            story.append(paragraph(line.strip()[2:], styles['BulletText'], prefix='• '))
        # Numbered lists
        elif re.match(r'^\d+\.\s', line.strip()):
            list_text = re.sub(r'^\d+\.\s', '', line.strip())
            num = re.match(r'^(\d+)\.', line.strip()).group(1)
            story.append(paragraph(list_text, styles['BulletText'], prefix=f'{num}. '))
        # Empty lines
        elif not line.strip():
            story.append(Spacer(1, 0.15*inch))
        # Regular paragraphs
        else:
            story.append(paragraph(line, styles['Normal']))

    try:
        doc.build(story)
    except Exception as e:
        # Never lose the document over its formatting: every line, plain.
        print(f"[ARTIFACT] PDF build failed ({e}); rebuilding as plain text")
        plain = [Paragraph(escape_xml(line), styles['Normal']) if line.strip() else Spacer(1, 0.15*inch)
                 for line in lines]
        SimpleDocTemplate(str(output_path), pagesize=letter,
                          leftMargin=inch, rightMargin=inch,
                          topMargin=inch, bottomMargin=inch).build(plain)

def generate_csv(content: str, output_path: Path):
    """Generate CSV file from content.
    Content should be comma-separated values with newlines between rows.
    """
    # CSV is just text - write directly
    output_path.write_text(content, encoding='utf-8')

def generate_docx(content: str, output_path: Path):
    """Generate DOCX from markdown-like content using python-docx."""
    from docx import Document
    from docx.shared import Pt, Inches
    from docx.enum.text import WD_ALIGN_PARAGRAPH

    doc = Document()

    lines = content.split('\n')
    for line in lines:
        # Headers
        if line.startswith('# '):
            p = doc.add_heading(line[2:], level=1)
        elif line.startswith('## '):
            p = doc.add_heading(line[3:], level=2)
        elif line.startswith('### '):
            p = doc.add_heading(line[4:], level=3)
        # Bullet points
        elif line.strip().startswith('- ') or line.strip().startswith('* '):
            p = doc.add_paragraph(line.strip()[2:], style='List Bullet')
        # Numbered lists
        elif re.match(r'^\d+\.\s', line.strip()):
            list_text = re.sub(r'^\d+\.\s', '', line.strip())
            p = doc.add_paragraph(list_text, style='List Number')
        # Empty lines - add paragraph break
        elif not line.strip():
            doc.add_paragraph()
        # Regular paragraphs
        else:
            p = doc.add_paragraph()
            # Process inline formatting
            remaining = line
            while remaining:
                # Bold: **text**
                bold_match = re.search(r'\*\*(.+?)\*\*', remaining)
                # Italic: *text*
                italic_match = re.search(r'(?<!\*)\*([^*]+)\*(?!\*)', remaining)

                if bold_match and (not italic_match or bold_match.start() <= italic_match.start()):
                    # Add text before bold
                    if bold_match.start() > 0:
                        p.add_run(remaining[:bold_match.start()])
                    # Add bold text
                    run = p.add_run(bold_match.group(1))
                    run.bold = True
                    remaining = remaining[bold_match.end():]
                elif italic_match:
                    # Add text before italic
                    if italic_match.start() > 0:
                        p.add_run(remaining[:italic_match.start()])
                    # Add italic text
                    run = p.add_run(italic_match.group(1))
                    run.italic = True
                    remaining = remaining[italic_match.end():]
                else:
                    # No more formatting, add rest as plain text
                    p.add_run(remaining)
                    break

    doc.save(str(output_path))

# Media types a browser renders as an active document (script runs in the
# serving origin) when it NAVIGATES to the file, plus the script types a later
# Content-Security-Policy would trust from 'self'.
_ACTIVE_MEDIA_TYPES = frozenset({
    "text/html", "text/xsl", "text/x-component", "application/hta",
    "text/javascript", "application/javascript", "application/x-javascript",
    "text/ecmascript", "application/ecmascript",
})

# Appended to the on-disk name of an artifact whose model-chosen name is
# active (see stored_artifact_name). Distinctive on purpose: ordinary names
# never end with it, so their ids and links stay exactly as they were.
INERT_SUFFIX = ".inert.txt"


def _is_active_name(name: str) -> bool:
    """True when a static file server would type `name` as an active document.

    Uses mimetypes.guess_type, exactly as Starlette's StaticFiles/FileResponse
    do, so the answer matches what /ui would send (case-insensitive extensions,
    .html.gz -> text/html, and any extra mappings in /etc/mime.types).
    """
    media_type = (mimetypes.guess_type(name)[0] or "").lower()
    return (
        media_type in _ACTIVE_MEDIA_TYPES
        or media_type.endswith(("/xml", "+xml"))
        or media_type.startswith(("multipart/", "message/"))
    )


def stored_artifact_name(artifact_id: str) -> str:
    """The on-disk name for an artifact id built from a model-chosen filename.

    ARTIFACTS_DIR is Portal/artifacts, which the /ui StaticFiles mount ALSO
    serves inline, typed by extension. A prompt-injected reply can name its
    artifact "report.html" (or .svg, .xhtml, .xml, .js ...), and that file would
    then run as a page with full Portal privileges at /ui/artifacts/<id>. Such
    names get INERT_SUFFIX, so every server types them text/plain. Names that
    already end in INERT_SUFFIX get it too, which keeps the mapping reversible
    for every name (artifact_download_name undoes exactly one suffix).
    """
    if _is_active_name(artifact_id) or artifact_id.endswith(INERT_SUFFIX):
        return artifact_id + INERT_SUFFIX
    return artifact_id


def artifact_download_name(stored_name: str) -> str:
    """The name to download a stored artifact as: the model's original name."""
    if stored_name.endswith(INERT_SUFFIX):
        return stored_name[:-len(INERT_SUFFIX)]
    return stored_name


def parse_and_process_artifacts_with_meta(ui_reply: str, operator: str):
    """
    Parse [ARTIFACT:...] blocks, generate files, replace with download links.

    Returns a tuple (modified_ui_reply, artifacts_list) where:
      - modified_ui_reply is byte-identical to what parse_and_process_artifacts
        has always returned (Portal depends on this exact HTML).
      - artifacts_list is a list of dicts, one per SUCCESSFULLY generated artifact:
            {"filename": str, "type": str, "url": "/artifacts/<id>", "size_kb": float}
        image_placeholder artifacts (no file) and error cases (no file) are NOT
        included. This structured form lets native clients (e.g. Android, Phase 6b)
        render download chips instead of parsing the [ARTIFACT] text / HTML.
    """
    pattern = r'\[ARTIFACT:([^:]+):([^\]]+)\](.*?)\[/ARTIFACT\]'

    artifacts_list = []
    operator_prefix = safe_filename(operator, fallback="operator")

    def process_match(match):
        # The tag's filename is model-supplied: reduce it to a safe basename so
        # it can neither leave ARTIFACTS_DIR nor break out of the HTML below.
        filename = safe_filename(match.group(1).strip(), fallback="artifact.txt")
        artifact_type = match.group(2).strip().lower()
        content = match.group(3).strip()
        # filename, type and error text come from model output (a prompt-injected
        # page or email can make the model emit the tag), and this HTML is rendered
        # by the Portal and kept in history: escape every interpolated value. For
        # ordinary names escaping is the identity, so the Portal's HTML is unchanged.
        html_filename = html.escape(filename, quote=True)

        print(f"[ARTIFACT] Processing: filename={filename}, type={artifact_type}, content_len={len(content)}")

        # Generate unique filename with operator prefix. Routes validate the
        # operator first; the prefix is reduced here too so no caller can steer
        # the write elsewhere. A name a browser would run as a page gets an inert
        # on-disk suffix (the download keeps the name).
        artifact_id = stored_artifact_name(f"{operator_prefix}_{uuid.uuid4().hex[:8]}_{filename}")
        artifact_path = ARTIFACTS_DIR / artifact_id
        if not artifact_path.resolve().is_relative_to(Path(ARTIFACTS_DIR).resolve()):
            return '<div class="artifact-error" style="color: #ff6b6b; padding: 8px; background: #1a1a1a; border-radius: 4px;">⚠️ Refused artifact path</div>'

        try:
            if artifact_type == 'text':
                artifact_path.write_text(content, encoding='utf-8')
            elif artifact_type == 'pdf':
                generate_pdf(content, artifact_path)
            elif artifact_type == 'csv':
                generate_csv(content, artifact_path)
            elif artifact_type == 'docx':
                generate_docx(content, artifact_path)
            elif artifact_type == 'image_placeholder':
                # Special handling for image generation placeholders created by AI models
                # Don't create a file - just return empty string since the image_task event handles the actual display
                print(f"[ARTIFACT] Ignoring image_placeholder artifact - handled by task manager")
                return ''
            else:
                return f'<div class="artifact-error" style="color: #ff6b6b; padding: 8px; background: #1a1a1a; border-radius: 4px;">⚠️ Unsupported artifact type: {html.escape(artifact_type, quote=True)}</div>'

            # Return download button HTML
            size_kb = artifact_path.stat().st_size / 1024
            print(f"[ARTIFACT] Success: {filename} ({size_kb:.1f} KB)")
            # Structured metadata for native clients (only successful, file-backed artifacts)
            artifacts_list.append({
                "filename": filename,
                "type": artifact_type,
                "url": f"/artifacts/{artifact_id}",
                "size_kb": round(size_kb, 1),
            })
            safe_href = html.escape(f"/artifacts/{artifact_id}", quote=True)
            return f'<div class="artifact-download"><a href="{safe_href}" download="{html_filename}" class="btn artifact-btn">📥 Download {html_filename} ({size_kb:.1f} KB)</a></div>'
        except Exception as e:
            print(f"[ARTIFACT] Error generating {filename} (type={artifact_type}): {e}")
            import traceback
            traceback.print_exc()
            # Show more helpful error in UI
            error_msg = str(e)
            if len(error_msg) > 200:
                error_msg = error_msg[:200] + "..."
            return f'<div class="artifact-error" style="color: #ff6b6b; padding: 12px; background: #1a1a1a; border-radius: 4px; margin: 8px 0;">⚠️ Failed to generate {html_filename}: {html.escape(error_msg, quote=True)}</div>'

    modified = re.sub(pattern, process_match, ui_reply, flags=re.DOTALL)
    return modified, artifacts_list


def parse_and_process_artifacts(ui_reply: str, operator: str) -> str:
    """
    Back-compat wrapper: parse [ARTIFACT:...] blocks, generate files, replace
    with download links, and return ONLY the modified ui_reply string.

    Thin wrapper around parse_and_process_artifacts_with_meta so existing callers
    (admin_routes.reprocess, Portal-facing paths) keep their exact behavior.
    """
    modified, _artifacts = parse_and_process_artifacts_with_meta(ui_reply, operator)
    return modified

